    hemiSky: 0xcfe6ff, hemiGround: 0x50603e, hemiIntensity: 1.05,
    exposure: 1.0, ambient: 0.15, night: false,
    lightColor: 0xfff0d0,
  },
  sunset: {
    id: 'sunset',
    skyTop: 0x1c2452, skyHorizon: 0xff9a5e, skyGround: 0xb56a52,
    fog: 0xd08b70, fogNear: 120, fogFar: 820,
    sunDir: [-0.28, 0.16, -0.94], sunColor: 0xffb271, sunIntensity: 2.6,
    hemiSky: 0xffb98d, hemiGround: 0x3b3a52, hemiIntensity: 0.85,
    exposure: 1.12, ambient: 0.12, night: false,
    lightColor: 0xffb887,
  },
  night: {
    id: 'night',
    skyTop: 0x02040b, skyHorizon: 0x0c1830, skyGround: 0x05080f,
    fog: 0x081020, fogNear: 70, fogFar: 560,
    sunDir: [-0.35, 0.62, -0.7], sunColor: 0xa9c6ff, sunIntensity: 0.55,
    hemiSky: 0x4c6ea8, hemiGround: 0x10131c, hemiIntensity: 0.55,
    exposure: 1.25, ambient: 0.08, night: true,
    lightColor: 0xbcd4ff,
  },
};

function skyMaterial(theme) {
  return new THREE.ShaderMaterial({
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
    uniforms: {
      uTop: { value: new THREE.Color(theme.skyTop) },
      uHorizon: { value: new THREE.Color(theme.skyHorizon) },
      uGround: { value: new THREE.Color(theme.skyGround) },
      uSunDir: { value: new THREE.Vector3(...theme.sunDir).normalize() },
      uSunColor: { value: new THREE.Color(theme.sunColor) },
      uSunPower: { value: theme.night ? 600 : 260 },
      uSunGlow: { value: theme.night ? 0.25 : 0.7 },
      uNight: { value: theme.night ? 1 : 0 },
    },
    vertexShader: `
      varying vec3 vDir;
      void main() {
        vDir = normalize(position);
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: `
      uniform vec3 uTop, uHorizon, uGround, uSunDir, uSunColor;
      uniform float uSunPower, uSunGlow, uNight;
      varying vec3 vDir;
      void main() {
        vec3 d = normalize(vDir);
        float h = d.y;
        vec3 col = mix(uHorizon, uTop, pow(smoothstep(0.0, 0.55, h), 0.8));
        col = mix(col, uGround, smoothstep(0.0, -0.18, h));
        float sd = max(dot(d, uSunDir), 0.0);
        col += uSunColor * pow(sd, uSunPower) * (uNight > 0.5 ? 0.4 : 1.4);
        col += uSunColor * pow(sd, 7.0) * uSunGlow * (1.0 - uNight * 0.5);
        // faint haze band on the horizon
        col += uHorizon * 0.16 * exp(-abs(h) * 14.0);
        gl_FragColor = vec4(col, 1.0);
        #include <tonemapping_fragment>
        #include <colorspace_fragment>
      }
    `,
  });
}

function cloudTexture() {
  const s = 256;
  const c = document.createElement('canvas');
  c.width = s; c.height = s;
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, s, s);
  for (let i = 0; i < 16; i++) {
    const x = s * 0.5 + (Math.random() - 0.5) * s * 0.55;
    const y = s * 0.55 + (Math.random() - 0.5) * s * 0.2;
    const r = s * (0.12 + Math.random() * 0.2);
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, 'rgba(255,255,255,0.5)');
    g.addColorStop(0.55, 'rgba(255,255,255,0.22)');
    g.addColorStop(1, 'rgba(255,255,255,0)');
    ctx.fillStyle = g;
    ctx.fillRect(0, 0, s, s);
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export function setupEnvironment(scene, theme, renderer) {
  scene.background = new THREE.Color(theme.skyHorizon);
  scene.fog = new THREE.Fog(theme.fog, theme.fogNear, theme.fogFar);

  const sky = new THREE.Mesh(new THREE.SphereGeometry(1700, 48, 32), skyMaterial(theme));
  scene.add(sky);

  const hemi = new THREE.HemisphereLight(theme.hemiSky, theme.hemiGround, theme.hemiIntensity);
  scene.add(hemi);
  const amb = new THREE.AmbientLight(theme.lightColor, theme.ambient);
  scene.add(amb);

  const sunDir = new THREE.Vector3(...theme.sunDir).normalize();
  const sun = new THREE.DirectionalLight(theme.sunColor, theme.sunIntensity);
  sun.position.copy(sunDir).multiplyScalar(160);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.near = 1;
  sun.shadow.camera.far = 420;
  sun.shadow.camera.left = -55;
  sun.shadow.camera.right = 55;
  sun.shadow.camera.top = 55;
  sun.shadow.camera.bottom = -55;
  sun.shadow.bias = -0.0004;
  sun.shadow.normalBias = 0.03;
  scene.add(sun);
  scene.add(sun.target);

  // sun / moon disc
  const sunGlowTex = glowTexture(theme.night ? 'rgba(215,232,255,0.95)' : 'rgba(255,230,180,0.95)');
  const flare = new THREE.Sprite(new THREE.SpriteMaterial({
    map: sunGlowTex, transparent: true, depthWrite: false, depthTest: false,
    blending: THREE.AdditiveBlending, opacity: theme.night ? 0.55 : 0.9, fog: false,
  }));
  flare.scale.setScalar(theme.night ? 130 : 260);
  flare.position.copy(sunDir).multiplyScalar(1100);
  flare.renderOrder = -2;
  scene.add(flare);

  // stars at night
  let stars = null;
  if (theme.night) {
    const pos = [];
    for (let i = 0; i < 1400; i++) {
      const v = new THREE.Vector3(Math.random() * 2 - 1, Math.random() * 1.1, Math.random() * 2 - 1).normalize().multiplyScalar(1500);
      if (v.y < 25) continue;
      pos.push(v.x, v.y, v.z);
    }
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
    const starsMat = new THREE.PointsMaterial({
      color: 0xdce9ff, size: 3.4, sizeAttenuation: true, transparent: true,
      opacity: 0.9, depthWrite: false, fog: false,
    });
    stars = new THREE.Points(g, starsMat);
    stars.renderOrder = -1;
    scene.add(stars);
  }

  // clouds for day / sunset
  let clouds = null;
  if (!theme.night) {
    clouds = new THREE.Group();
    const tex = cloudTexture();
    const mat = new THREE.SpriteMaterial({
      map: tex, transparent: true, opacity: theme.id === 'sunset' ? 0.42 : 0.5,
      depthWrite: false, color: theme.id === 'sunset' ? 0xffb39a : 0xffffff, fog: false,
    });
    for (let i = 0; i < 16; i++) {
      const a = Math.random() * Math.PI * 2;
      const r = 650 + Math.random() * 650;
      const sp = new THREE.Sprite(mat);
      sp.position.set(Math.cos(a) * r, 130 + Math.random() * 220, Math.sin(a) * r);
      const sc = 220 + Math.random() * 380;
      sp.scale.set(sc, sc * 0.42, 1);
      sp.renderOrder = -1;
      clouds.add(sp);
    }
    scene.add(clouds);
  }

  return { sun, sunDir, hemi, amb, sky, flare, stars, clouds, theme };
}

export class Particles {
  constructor(scene, { count = 220, texture, color = 0xffffff, additive = true, size = 2 }) {
    this.count = count;
    this.positions = new Float32Array(count * 3);
    this.colors = new Float32Array(count * 3);
    this.sizes = new Float32Array(count);
    this.alphas = new Float32Array(count);
    this.life = new Float32Array(count);
    this.maxLife = new Float32Array(count);
    this.vel = new Float32Array(count * 3);
    this.cursor = 0;
    const g = new THREE.BufferGeometry();
    g.setAttribute('position', new THREE.BufferAttribute(this.positions, 3));
    g.setAttribute('aColor', new THREE.BufferAttribute(this.colors, 3));
    g.setAttribute('aSize', new THREE.BufferAttribute(this.sizes, 1));
    g.setAttribute('aAlpha', new THREE.BufferAttribute(this.alphas, 1));
    const mat = new THREE.ShaderMaterial({
      uniforms: { uMap: { value: texture } },
      vertexShader: `
        attribute vec3 aColor; attribute float aSize; attribute float aAlpha;
        varying vec3 vColor; varying float vAlpha;
        void main() {
          vColor = aColor; vAlpha = aAlpha;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = aSize * (280.0 / max(0.001, -mv.z));
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: `
        uniform sampler2D uMap; varying vec3 vColor; varying float vAlpha;
        void main() {
          vec4 t = texture2D(uMap, gl_PointCoord);
          if (t.a * vAlpha < 0.01) discard;
          gl_FragColor = vec4(vColor, t.a * vAlpha);
        }
      `,
      transparent: true,
      depthWrite: false,
      blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
    });
    this.points = new THREE.Points(g, mat);
    this.points.frustumCulled = false;
    scene.add(this.points);
    this.geometry = g;
    this.baseColor = new THREE.Color(color);
  }

  spawn(pos, vel, opts = {}) {
    const i = this.cursor;
    this.cursor = (this.cursor + 1) % this.count;
    this.positions[i * 3] = pos.x;
    this.positions[i * 3 + 1] = pos.y;
    this.positions[i * 3 + 2] = pos.z;
    this.vel[i * 3] = vel.x;
    this.vel[i * 3 + 1] = vel.y;
    this.vel[i * 3 + 2] = vel.z;
    const c = new THREE.Color(opts.color ?? this.baseColor);
    this.colors[i * 3] = c.r; this.colors[i * 3 + 1] = c.g; this.colors[i * 3 + 2] = c.b;
    this.sizes[i] = opts.size ?? 1;
    this.life[i] = this.maxLife[i] = opts.life ?? 0.8;
    this.alphas[i] = opts.alpha ?? 0.7;
  }

  update(dt) {
    for (let i = 0; i < this.count; i++) {
      if (this.life[i] <= 0) { this.alphas[i] = 0; continue; }
      this.life[i] -= dt;
      const f = Math.max(0, this.life[i] / this.maxLife[i]);
      this.alphas[i] = f * 0.7;
      this.positions[i * 3] += this.vel[i * 3] * dt;
      this.positions[i * 3 + 1] += this.vel[i * 3 + 1] * dt;
      this.positions[i * 3 + 2] += this.vel[i * 3 + 2] * dt;
      this.vel[i * 3 + 1] += 1.6 * dt;
      this.sizes[i] *= 1 + dt * 1.4;
    }
    this.geometry.attributes.position.needsUpdate = true;
    this.geometry.attributes.aAlpha.needsUpdate = true;
    this.geometry.attributes.aSize.needsUpdate = true;
    this.geometry.attributes.aColor.needsUpdate = true;
  }
}

export function makeParticleSystems(scene) {
  const smoke = new Particles(scene, { count: 240, texture: smokeTexture(), color: 0xd8cdb8, additive: false, size: 2.6 });
  const sparks = new Particles(scene, { count: 90, texture: glowTexture('rgba(255,220,160,1)'), color: 0xffc46a, additive: true, size: 0.7 });
  const flames = new Particles(scene, { count: 80, texture: glowTexture('rgba(255,190,90,1)'), color: 0xff8a2a, additive: true, size: 1.1 });
  return { smoke, sparks, flames };
}

import * as THREE from 'three';
import { GLTFLoader } from 'three/addons/loaders/GLTFLoader.js';
import { glowTexture, nameTexture } from './textures.js';

const BIKE_FILES = [
  { url: './assets/models/sportbike.glb', yaw: -Math.PI / 2, name: 'VIPER R1' },
  { url: './assets/models/sportbike2.glb', yaw: Math.PI, name: 'FALCON M2' },
];

function normalizeBike(scene, yaw) {
  const wrap = new THREE.Group();
  const inner = scene;
  inner.updateMatrixWorld(true);
  const box = new THREE.Box3().setFromObject(inner);
  const center = new THREE.Vector3();
  const size = new THREE.Vector3();
  box.getSize(size);
  box.getCenter(center);
  inner.position.set(-center.x, -box.min.y, -center.z);
  inner.rotation.y = yaw;
  inner.traverse(o => {
    if (!o.isMesh) return;
    o.castShadow = true;
    o.receiveShadow = false;
    o.frustumCulled = true;
    const mats = Array.isArray(o.material) ? o.material : [o.material];
    for (const m of mats) {
      if (!m) continue;
      m.envMapIntensity = 0.85;
      if (m.map) m.map.colorSpace = THREE.SRGBColorSpace;
      m.roughness = Math.min(0.95, (m.roughness ?? 0.5) * 0.95 + 0.05);
    }
  });
  wrap.add(inner);
  wrap.userData.size = size;
  return wrap;
}

export async function loadBikeTemplates(onProgress) {
  const loader = new GLTFLoader();
  const templates = [];
  for (let i = 0; i < BIKE_FILES.length; i++) {
    const file = BIKE_FILES[i];
    const gltf = await loader.loadAsync(file.url);
    const wrap = normalizeBike(gltf.scene, file.yaw);
    wrap.userData.name = file.name;
    wrap.userData.index = i;
    templates.push(wrap);
    if (onProgress) onProgress((i + 1) / BIKE_FILES.length);
  }
  return templates;
}

function capsuleBetween(a, b, radius, mat, radial = 12) {
  const dir = new THREE.Vector3().subVectors(b, a);
  const len = dir.length();
  const geo = new THREE.CapsuleGeometry(radius, Math.max(0.01, len - radius * 2), 5, radial);
  const mesh = new THREE.Mesh(geo, mat);
  mesh.position.copy(a).add(b).multiplyScalar(0.5);
  mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
  mesh.castShadow = true;
  return mesh;
}

function buildRider(accent) {
  const g = new THREE.Group();
  g.name = 'rider';
  const suit = new THREE.MeshStandardMaterial({ color: 0x14171d, roughness: 0.52, metalness: 0.12 });
  const suit2 = new THREE.MeshStandardMaterial({ color: 0x242a34, roughness: 0.6, metalness: 0.1 });
  const accentMat = new THREE.MeshStandardMaterial({ color: accent, roughness: 0.35, metalness: 0.25, emissive: accent, emissiveIntensity: 0.13 });
  const white = new THREE.MeshStandardMaterial({ color: 0xe8ecf2, roughness: 0.45, metalness: 0.1 });
  const visorMat = new THREE.MeshStandardMaterial({ color: 0x0a1420, roughness: 0.08, metalness: 0.95, emissive: 0x0a2440, emissiveIntensity: 0.5 });
  const bootMat = new THREE.MeshStandardMaterial({ color: 0x0c0e12, roughness: 0.65 });

  const hips = new THREE.Vector3(0, 0.94, 0.16);
  const shoulders = new THREE.Vector3(0, 1.26, -0.15);
  const head = new THREE.Vector3(0, 1.43, -0.35);
  const hipsL = new THREE.Vector3(0.135, 0.93, 0.15);
  const hipsR = new THREE.Vector3(-0.135, 0.93, 0.15);

  // pelvis + torso
  const pelvis = new THREE.Mesh(new THREE.SphereGeometry(0.17, 14, 10), suit2);
  pelvis.scale.set(1.15, 0.8, 1);
  pelvis.position.copy(hips);
  pelvis.castShadow = true;
  g.add(pelvis);

  g.add(capsuleBetween(new THREE.Vector3(0, 0.99, 0.11), new THREE.Vector3(0, 1.24, -0.14), 0.155, suit, 14));
  const chest = new THREE.Mesh(new THREE.SphereGeometry(0.185, 16, 12), suit);
  chest.position.set(0, 1.2, -0.08);
  chest.scale.set(1.15, 0.85, 1.25);
  chest.castShadow = true;
  g.add(chest);
  // racing hump
  const hump = new THREE.Mesh(new THREE.SphereGeometry(0.14, 12, 10), accentMat);
  hump.position.set(0, 1.22, 0.18);
  hump.scale.set(1, 0.9, 1.6);
  hump.castShadow = true;
  g.add(hump);
  const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.34, 0.035, 0.02), white);
  stripe.position.set(0, 1.245, -0.205);
  stripe.rotation.x = -0.75;
  g.add(stripe);

  // helmet
  const helmet = new THREE.Mesh(new THREE.SphereGeometry(0.178, 20, 16), accentMat);
  helmet.position.copy(head);
  helmet.scale.set(0.94, 1.0, 1.06);
  helmet.castShadow = true;
  g.add(helmet);
  const visor = new THREE.Mesh(new THREE.SphereGeometry(0.155, 18, 12), visorMat);
  visor.position.set(0, 1.44, -0.43);
  visor.scale.set(0.86, 0.66, 0.62);
  g.add(visor);
  const chin = new THREE.Mesh(new THREE.SphereGeometry(0.12, 14, 10), suit2);
  chin.position.set(0, 1.355, -0.35);
  chin.scale.set(0.9, 0.75, 1.1);
  g.add(chin);

  // arms
  for (const side of [1, -1]) {
    const sh = new THREE.Vector3(side * 0.16, 1.24, -0.14);
    const elbow = new THREE.Vector3(side * 0.3, 1.08, -0.4);
    const hand = new THREE.Vector3(side * 0.28, 0.99, -0.62);
    g.add(capsuleBetween(sh, elbow, 0.065, suit, 8));
    g.add(capsuleBetween(elbow, hand, 0.052, suit2, 8));
    const glove = new THREE.Mesh(new THREE.SphereGeometry(0.055, 10, 8), accentMat);
    glove.position.copy(hand);
    g.add(glove);
    const shoulder = new THREE.Mesh(new THREE.SphereGeometry(0.09, 10, 8), accentMat);
    shoulder.position.copy(sh);
    g.add(shoulder);
    // legs (knee up, boot back)
    const hipP = side > 0 ? hipsL : hipsR;
    const knee = new THREE.Vector3(side * 0.29, 0.77, -0.2);
    const foot = new THREE.Vector3(side * 0.31, 0.46, 0.16);
    g.add(capsuleBetween(hipP, knee, 0.082, suit, 8));
    g.add(capsuleBetween(knee, foot, 0.065, suit2, 8));
    const kneePad = new THREE.Mesh(new THREE.SphereGeometry(0.075, 10, 8), accentMat);
    kneePad.position.copy(knee);
    g.add(kneePad);
    const boot = new THREE.Mesh(new THREE.BoxGeometry(0.11, 0.1, 0.24), bootMat);
    boot.position.copy(foot).add(new THREE.Vector3(0, -0.02, -0.04));
    boot.rotation.x = 0.25;
    boot.castShadow = true;
    g.add(boot);
  }

  return g;
}

export function createBikeVisual(template, opts = {}) {
  const root = new THREE.Group();
  const lean = new THREE.Group();
  root.add(lean);

  const model = template.clone(true);
  model.traverse(o => {
    if (o.isMesh) { o.castShadow = true; o.receiveShadow = false; }
  });
  lean.add(model);

  const accent = new THREE.Color(opts.accent ?? 0xff6b1a);
  const rider = buildRider(accent);
  lean.add(rider);

  // accent strips on the tail
  const stripMat = new THREE.MeshStandardMaterial({
    color: accent, emissive: accent, emissiveIntensity: 0.9, roughness: 0.4, metalness: 0.2,
  });
  for (const side of [-1, 1]) {
    const strip = new THREE.Mesh(new THREE.BoxGeometry(0.026, 0.11, 0.62), stripMat);
    strip.position.set(side * 0.155, 0.79, 0.62);
    strip.rotation.x = -0.08;
    lean.add(strip);
  }

  // soft ground glow, mainly visible at night
  const glow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTexture('rgba(255,255,255,0.85)'), color: accent, transparent: true,
    opacity: opts.night ? 0.5 : 0.16, blending: THREE.AdditiveBlending, depthWrite: false,
  }));
  glow.scale.set(2.6, 2.6, 1);
  glow.position.y = 0.09;
  root.add(glow);

  // exhaust flame
  const flame = new THREE.Group();
  const flameMat = new THREE.MeshBasicMaterial({
    color: 0xff9a3c, transparent: true, opacity: 0.85, blending: THREE.AdditiveBlending,
    depthWrite: false, side: THREE.DoubleSide,
  });
  const cone = new THREE.Mesh(new THREE.ConeGeometry(0.14, 1.6, 10, 1, true), flameMat);
  cone.rotation.x = Math.PI / 2;
  cone.position.z = 0.82;
  flame.add(cone);
  const flameGlow = new THREE.Sprite(new THREE.SpriteMaterial({
    map: glowTexture('rgba(255,190,90,1)'), color: 0xffa040, transparent: true,
    opacity: 0.9, blending: THREE.AdditiveBlending, depthWrite: false,
  }));
  flameGlow.scale.set(1.3, 1.3, 1);
  flameGlow.position.z = 0.9;
  flame.add(flameGlow);
  flame.position.set(0, 0.62, 0.55);
  flame.visible = false;
  lean.add(flame);

  // headlight for night races
  let headlight = null;
  if (opts.night) {
    headlight = new THREE.SpotLight(0xfff1d0, 55, 65, 0.42, 0.55, 1.3);
    headlight.position.set(0, 0.95, -0.62);
    headlight.target.position.set(0, 0.2, -26);
    lean.add(headlight);
    lean.add(headlight.target);
    const shaftMat = new THREE.MeshBasicMaterial({
      color: 0xffe4b0, transparent: true, opacity: 0.05, blending: THREE.AdditiveBlending,
      depthWrite: false, side: THREE.DoubleSide,
    });
    const shaft = new THREE.Mesh(new THREE.ConeGeometry(2.4, 17, 18, 1, true), shaftMat);
    shaft.rotation.x = -Math.PI / 2;
    shaft.position.set(0, 0.82, -8.8);
    shaft.rotation.z = Math.PI;
    lean.add(shaft);
  }

  // name tag overhead
  let tag = null;
  if (opts.name) {
    const tex = nameTexture(opts.name, '#' + accent.getHexString());
    tag = new THREE.Sprite(new THREE.SpriteMaterial({
      map: tex, transparent: true, depthWrite: false, opacity: 0.9, fog: false,
    }));
    tag.scale.set(2.6, 0.65, 1);
    tag.position.set(0, 2.25, 0.2);
    root.add(tag);
  }

  return {
    root, lean, model, rider, accent, glow, flame, headlight, tag,
    setPose(leanAngle, pitch, bob) {
      this.lean.rotation.z = leanAngle;
      this.lean.rotation.x = pitch;
      this.lean.position.y = bob;
      this.rider.rotation.z = -leanAngle * 0.12;
      this.rider.rotation.x = Math.max(0, pitch) * 0.6;
    },
    setBoost(on, time) {
      this.flame.visible = on;
      if (on) {
        const s = 0.9 + Math.sin(time * 45) * 0.18 + Math.random() * 0.12;
        this.flame.scale.set(1, s, 1);
        this.flameGlow.material.opacity = 0.55 + Math.random() * 0.35;
      }
    },
    setTagVisible(v) { if (this.tag) this.tag.visible = v; },
    setTagOpacity(v) { if (this.tag) this.tag.material.opacity = v; },
    dispose() {
      this.root.traverse(o => {
        if (o.isMesh && o.geometry && o.userData.shared !== true) {
          // geometry is shared with the template, so only dispose materials we created
        }
      });
    },
  };
}

export function createShowroomBike(template) {
  const root = new THREE.Group();
  const model = template.clone(true);
  model.traverse(o => { if (o.isMesh) { o.castShadow = true; o.receiveShadow = false; } });
  root.add(model);
  return root;
}

export class AudioSystem {
  constructor() {
    this.ctx = null;
    this.enabled = true;
    this.started = false;
    this.master = null;
    this.engineGain = null;
    this.windGain = null;
    this.skidGain = null;
    this.musicGain = null;
    this.nextNote = 0;
    this.step = 0;
    this.musicTimer = null;
    this.lastSkid = 0;
  }

  init() {
    if (this.ctx) return;
    const AC = window.AudioContext || window.webkitAudioContext;
    if (!AC) return;
    this.ctx = new AC();
    this.master = this.ctx.createGain();
    this.master.gain.value = this.enabled ? 0.75 : 0;
    this.master.connect(this.ctx.destination);

    // engine
    this.engineGain = this.ctx.createGain();
    this.engineGain.gain.value = 0;
    this.engineFilter = this.ctx.createBiquadFilter();
    this.engineFilter.type = 'lowpass';
    this.engineFilter.frequency.value = 700;
    this.engineFilter.Q.value = 3;
    this.engineGain.connect(this.engineFilter);
    this.engineFilter.connect(this.master);

    this.oscA = this.ctx.createOscillator();
    this.oscA.type = 'sawtooth';
    this.oscA.frequency.value = 60;
    this.oscB = this.ctx.createOscillator();
    this.oscB.type = 'square';
    this.oscB.frequency.value = 30;
    this.oscC = this.ctx.createOscillator();
    this.oscC.type = 'sawtooth';
    this.oscC.frequency.value = 121;
    const gA = this.ctx.createGain(); gA.gain.value = 0.55;
    const gB = this.ctx.createGain(); gB.gain.value = 0.28;
    const gC = this.ctx.createGain(); gC.gain.value = 0.18;
    this.oscA.connect(gA); gA.connect(this.engineGain);
    this.oscB.connect(gB); gB.connect(this.engineGain);
    this.oscC.connect(gC); gC.connect(this.engineGain);
    this.oscA.start(); this.oscB.start(); this.oscC.start();

    // wind
    const windBuf = this.noiseBuffer(2.5);
    const windSrc = this.ctx.createBufferSource();
    windSrc.buffer = windBuf; windSrc.loop = true;
    this.windFilter = this.ctx.createBiquadFilter();
    this.windFilter.type = 'bandpass';
    this.windFilter.frequency.value = 700;
    this.windFilter.Q.value = 0.7;
    this.windGain = this.ctx.createGain();
    this.windGain.gain.value = 0;
    windSrc.connect(this.windFilter); this.windFilter.connect(this.windGain); this.windGain.connect(this.master);
    windSrc.start();

    // skid
    const skidSrc = this.ctx.createBufferSource();
    skidSrc.buffer = windBuf; skidSrc.loop = true;
    const skidFilter = this.ctx.createBiquadFilter();
    skidFilter.type = 'bandpass'; skidFilter.frequency.value = 2300; skidFilter.Q.value = 4;
    this.skidGain = this.ctx.createGain(); this.skidGain.gain.value = 0;
    skidSrc.connect(skidFilter); skidFilter.connect(this.skidGain); this.skidGain.connect(this.master);
    skidSrc.start();

    // music bus
    this.musicGain = this.ctx.createGain();
    this.musicGain.gain.value = 0.18;
    this.musicGain.connect(this.master);

    this.started = true;
    this.scheduleMusic();
  }

  noiseBuffer(seconds) {
    const sr = this.ctx.sampleRate;
    const buf = this.ctx.createBuffer(1, sr * seconds, sr);
    const d = buf.getChannelData(0);
    let last = 0;
    for (let i = 0; i < d.length; i++) {
      const white = Math.random() * 2 - 1;
      last = (last + white * 0.04) * 0.995;
      d[i] = last * 8 + white * 0.4;
    }
    return buf;
  }

  setEnabled(v) {
    this.enabled = v;
    if (this.master) this.master.gain.setTargetAtTime(v ? 0.75 : 0, this.ctx.currentTime, 0.05);
  }

  resume() {
    if (this.ctx && this.ctx.state === 'suspended') this.ctx.resume();
  }

  setEngine(speed, throttle, boost) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const f = 48 + speed * 2.15 + (boost ? 22 : 0);
    this.oscA.frequency.setTargetAtTime(f, t, 0.06);
    this.oscB.frequency.setTargetAtTime(f * 0.5, t, 0.06);
    this.oscC.frequency.setTargetAtTime(f * 2.02, t, 0.06);
    this.engineFilter.frequency.setTargetAtTime(420 + speed * 32 + throttle * 450, t, 0.08);
    const vol = 0.035 + throttle * 0.04 + Math.min(0.03, speed * 0.0004);
    this.engineGain.gain.setTargetAtTime(vol, t, 0.09);
    this.windGain.gain.setTargetAtTime(Math.min(0.13, speed * 0.0022), t, 0.2);
    this.windFilter.frequency.setTargetAtTime(500 + speed * 22, t, 0.2);
  }

  setSkid(amount) {
    if (!this.ctx) return;
    this.skidGain.gain.setTargetAtTime(Math.min(0.09, amount * 0.09), this.ctx.currentTime, 0.06);
  }

  idle() {
    if (!this.ctx) return;
    this.engineGain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.2);
    this.windGain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.2);
    this.skidGain.gain.setTargetAtTime(0, this.ctx.currentTime, 0.1);
  }

  blip(freq = 620, dur = 0.09, type = 'square', vol = 0.12) {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = type; o.frequency.value = freq;
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t + dur + 0.02);
  }

  countdown(n) {
    if (n > 0) this.blip(420 + (3 - n) * 120, 0.16, 'square', 0.16);
    else this.blip(960, 0.55, 'sawtooth', 0.16);
  }

  crash() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer(0.8);
    const f = this.ctx.createBiquadFilter();
    f.type = 'lowpass'; f.frequency.value = 900;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(0.35, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.5);
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(t); src.stop(t + 0.55);
    this.blip(90, 0.25, 'sawtooth', 0.18);
  }

  scheduleMusic() {
    if (!this.ctx) return;
    const chords = [
      [110.0, 130.81, 164.81],
      [87.31, 110.0, 130.81],
      [98.0, 123.47, 146.83],
      [82.41, 103.83, 123.47],
    ];
    const arp = [
      [0, 2, 1, 2, 0, 2, 1, 2],
      [0, 3, 2, 3, 0, 3, 2, 3],
      [0, 2, 1, 2, 0, 2, 1, 2],
      [0, 3, 2, 3, 0, 3, 2, 3],
    ];
    const bpm = 104;
    const beat = 60 / bpm;
    const lookahead = 0.18;
    const tick = () => {
      if (!this.ctx) return;
      while (this.nextNote < this.ctx.currentTime + lookahead) {
        const t = this.nextNote;
        const bar = Math.floor(this.step / 8) % 4;
        const s8 = this.step % 8;
        const chord = chords[bar];
        // pad on bar start
        if (s8 === 0) {
          for (const f of chord) this.pad(f, t, beat * 8, 0.028);
          this.kick(t, 0.5);
          this.kick(t + beat * 4, 0.38);
        }
        // bass
        if (s8 % 2 === 0) this.bass(chord[0] / 2, t, beat * 0.85, 0.09);
        // arp
        const note = chord[arp[bar][s8]] * 4;
        this.pluck(note, t, beat * 0.5, 0.035);
        if (s8 === 4 || s8 === 7) this.hat(t, 0.02);
        this.nextNote += beat / 2;
        this.step++;
      }
    };
    this.nextNote = this.ctx.currentTime + 0.1;
    tick();
    this.musicTimer = setInterval(tick, 90);
  }

  pad(freq, t, dur, vol) {
    const o = this.ctx.createOscillator();
    const o2 = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    const f = this.ctx.createBiquadFilter();
    o.type = 'sawtooth'; o.frequency.value = freq;
    o2.type = 'sawtooth'; o2.frequency.value = freq * 1.006;
    f.type = 'lowpass'; f.frequency.value = 850; f.Q.value = 0.6;
    g.gain.setValueAtTime(0.0001, t);
    g.gain.exponentialRampToValueAtTime(vol, t + 0.6);
    g.gain.setValueAtTime(vol, t + dur - 0.5);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(f); o2.connect(f); f.connect(g); g.connect(this.musicGain);
    o.start(t); o2.start(t); o.stop(t + dur + 0.1); o2.stop(t + dur + 0.1);
  }

  bass(freq, t, dur, vol) {
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    const f = this.ctx.createBiquadFilter();
    o.type = 'sawtooth'; o.frequency.value = freq;
    f.type = 'lowpass'; f.frequency.setValueAtTime(420, t); f.frequency.exponentialRampToValueAtTime(110, t + dur);
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(f); f.connect(g); g.connect(this.musicGain);
    o.start(t); o.stop(t + dur + 0.02);
  }

  pluck(freq, t, dur, vol) {
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    const f = this.ctx.createBiquadFilter();
    o.type = 'triangle'; o.frequency.value = freq;
    f.type = 'lowpass'; f.frequency.value = 2600;
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + dur);
    o.connect(f); f.connect(g); g.connect(this.musicGain);
    o.start(t); o.stop(t + dur + 0.02);
  }

  kick(t, vol) {
    const o = this.ctx.createOscillator();
    const g = this.ctx.createGain();
    o.type = 'sine';
    o.frequency.setValueAtTime(110, t);
    o.frequency.exponentialRampToValueAtTime(42, t + 0.12);
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.16);
    o.connect(g); g.connect(this.musicGain);
    o.start(t); o.stop(t + 0.2);
  }

  hat(t, vol) {
    const src = this.ctx.createBufferSource();
    src.buffer = this.noiseBuffer(0.1);
    const f = this.ctx.createBiquadFilter();
    f.type = 'highpass'; f.frequency.value = 7000;
    const g = this.ctx.createGain();
    g.gain.setValueAtTime(vol, t);
    g.gain.exponentialRampToValueAtTime(0.0001, t + 0.06);
    src.connect(f); f.connect(g); g.connect(this.musicGain);
    src.start(t); src.stop(t + 0.1);
  }
}

