839: function updatePlayer(game, dt) {
840:   const p = game.player;
841:   const c = controls();
842:   const track = game.track;
843:   const halfW = track.halfWidth;
844:   const n = track.nearest(p.pos, p.hintIdx);
845:   p.hintIdx = n.idx;
846:   p.lateral = n.lateral;
847:   p.offroad = Math.abs(n.lateral) > halfW - 0.2;
848: 
849:   // steering smoothing
850:   const steerTarget = c.steer;
851:   p.steerVis = damp(p.steerVis, steerTarget, steerTarget !== 0 ? 8 : 11, dt);
852: 
853:   const speed = p.vel.length();
854:   const fwd = new THREE.Vector2(-Math.sin(p.yaw), -Math.cos(p.yaw));
855:   const right = new THREE.Vector2(Math.cos(p.yaw), -Math.sin(p.yaw));
856:   let vf = p.vel.dot(fwd);
857:   let vl = p.vel.dot(right);
858: 
859:   // engine
860:   const maxSpeed = c.nitro && p.nitro > 0.01 && vf > 4 ? 76 : 63;
861:   const speedRatio = clamp(vf / maxSpeed, 0, 1);
862:   let accel = 0;
863:   if (c.throttle) {
864:     accel = 23.5 * Math.pow(1 - speedRatio, 0.55) + 4.2;
865:     if (p.offroad) accel *= 0.34;
866:   }
867:   if (c.nitro && p.nitro > 0.01 && vf > 4) {
868:     accel += 15.5 * Math.pow(1 - speedRatio * 0.7, 0.8);
869:     p.nitro = Math.max(0, p.nitro - dt * 0.27);
870:     p.boost = true;
871:   } else {
872:     p.boost = false;
873:     p.nitro = Math.min(1, p.nitro + dt * 0.055);
874:   }
875:   if (c.brake) {
876:     if (vf > 0.5) accel -= 42;
877:     else if (!c.throttle) accel -= 7;
878:   }
879:   // coast / drag
880:   accel -= vf * Math.abs(vf) * 0.0022 + Math.sign(vf) * 0.55;
881:   if (p.offroad) accel -= vf * 0.55;
882: 
883:   vf += accel * dt;
884:   vf = clamp(vf, -9, maxSpeed);
885: 
886:   // lateral grip (drift feel off-road and at speed)
887:   const grip = p.offroad ? 2.2 : 7.2;
888:   vl *= Math.exp(-grip * dt);
889: 
890:   // steering
891:   const steerAuthority = lerp(2.25, 0.92, clamp(Math.abs(vf) / 68, 0, 1));
892:   const turn = p.steerVis * steerAuthority * (p.offroad ? 0.7 : 1);
