202:         attribute vec3 aColor; attribute float aSize; attribute float aAlpha;
203:         varying vec3 vColor; varying float vAlpha;
204:         void main() {
205:           vColor = aColor; vAlpha = aAlpha;
206:           vec4 mv = modelViewMatrix * vec4(position, 1.0);
207:           gl_PointSize = aSize * (280.0 / max(0.001, -mv.z));
208:           gl_Position = projectionMatrix * mv;
209:         }
