213:         void main() {
214:           vec4 t = texture2D(uMap, gl_PointCoord);
215:           if (t.a * vAlpha < 0.01) discard;
216:           gl_FragColor = vec4(vColor, t.a * vAlpha);
217:         }
218:       `,
219:       transparent: true,
220:       depthWrite: false,
221:       blending: additive ? THREE.AdditiveBlending : THREE.NormalBlending,
222:     });
223:     this.points = new THREE.Points(g, mat);
224:     this.points.frustumCulled = false;
225:     scene.add(this.points);
226:     this.geometry = g;
227:     this.baseColor = new THREE.Color(color);
