function ridgeGeometry(radius, minH, maxH, segments, phase, jitter) {
  const pos = [], idx = [];
  for (let i = 0; i <= segments; i++) {
    const a = (i / segments) * Math.PI * 2;
    const t = 0.5 + 0.3*Math.sin(a*2.0+phase) + 0.16*Math.sin(a*5.0+phase*1.7) + 0.09*Math.sin(a*9.0+phase*0.6) + 0.05*Math.sin(a*17.0+phase*2.3);
    const h = minH + (maxH-minH)*Math.max(0.05, Math.min(1, t));
    const rad = radius + Math.sin(a*4.0+phase)*radius*jitter;
    const x = Math.cos(a)*rad, z = Math.sin(a)*rad;
    pos.push(x, -20, z, x, h, z);
    if (i<segments) { const b=i*2; idx.push(b,b+2,b+1,b+1,b+2,b+3); }
  }
  const g=new THREE.BufferGeometry(); ...
  return g;
}
```

