function makeRidgeGeometry(radius, minH, maxH, segments, phase, jitter) {
  const pos = [], idx = [];
  for (let i = 0; i <= segments; i++) {
    const a = (i / segments) * Math.PI * 2;
    const t = 0.5 + 0.3 * Math.sin(a * 2 + phase) + 0.16 * Math.sin(a * 5 + phase * 1.7)
      + 0.09 * Math.sin(a * 9 + phase * 0.6) + 0.05 * Math.sin(a * 17 + phase * 2.3);
    const h = minH + (maxH - minH) * Math.max(0.04, Math.min(1, t));
    const rad = radius + Math.sin(a * 4 + phase) * radius * jitter;
    const x = Math.cos(a) * rad, z = Math.sin(a) * rad;
    pos.push(x, -24, z, x, h, z);
    if (i < segments) {
      const b = i * 2;
      idx.push(b, b + 2, b + 1, b + 1, b + 2, b + 3);
    }
  }
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.Float32BufferAttribute(pos, 3));
  g.setIndex(idx);
  g.computeVertexNormals();
  return g;
}

